#!/usr/bin/env bash
# =============================================================================
#  Création automatique de la VM "Hue Sync" sur Proxmox VE
#  - Debian 12 minimale (image cloud officielle "generic", sans interface graphique)
#  - passthrough de l'adaptateur Bluetooth USB de l'hôte
#  - installation automatique au 1er démarrage : AirPlay 2 + synchro Hue + interface web
#
#  Usage (en root sur l'hôte Proxmox) :
#     bash create-hue-sync-vm.sh
#  Options (variables d'environnement, toutes facultatives) :
#     VMID=130 NAME=hue-sync STORAGE=local-lvm BRIDGE=vmbr0 VLAN=20
#     MEMORY=1024 CORES=2 DISK=8G BT_USB=8087:0029 (ou BT_USB=none)
# =============================================================================
set -euo pipefail

say()  { printf '\033[1;36m==>\033[0m %s\n' "$*"; }
warn() { printf '\033[1;33m[!]\033[0m %s\n' "$*"; }
die()  { printf '\033[1;31m[x]\033[0m %s\n' "$*" >&2; exit 1; }

# Installeur de la VM (compressé, encodé en base64)
installer_b64() {
cat <<'HUE_B64_EOF'

HUE_B64_EOF
}

[ "$(id -u)" -eq 0 ] || die "Lance ce script en root sur l'hôte Proxmox."
command -v qm >/dev/null && command -v pvesm >/dev/null || die "Ce script doit tourner sur un hôte Proxmox VE."

NAME=${NAME:-hue-sync}
VMID=${VMID:-$(pvesh get /cluster/nextid)}
BRIDGE=${BRIDGE:-vmbr0}
VLAN=${VLAN:-}
MEMORY=${MEMORY:-1024}
CORES=${CORES:-2}
DISK=${DISK:-8G}
STORAGE=${STORAGE:-}
BT_USB=${BT_USB:-}
IMG_DIR=/var/lib/vz/template/cloud
IMG_NAME=debian-12-generic-amd64.qcow2
IMG_BASE=https://cloud.debian.org/images/cloud/bookworm/latest

qm status "$VMID" >/dev/null 2>&1 && die "La VM $VMID existe déjà. Choisis un autre numéro : VMID=xxx bash $0"

# --- Stockage des disques ----------------------------------------------------
if [ -z "$STORAGE" ]; then
  AVAIL=$(pvesm status --content images 2>/dev/null | awk 'NR>1 && $3=="active" {print $1}')
  for s in local-lvm local-zfs; do echo "$AVAIL" | grep -qx "$s" && { STORAGE=$s; break; }; done
  [ -n "$STORAGE" ] || STORAGE=$(echo "$AVAIL" | head -n1)
fi
[ -n "$STORAGE" ] || die "Aucun stockage pour disques de VM trouvé. Indique-le : STORAGE=xxx bash $0"

# --- Stockage des "snippets" (fichier cloud-init) -----------------------------
SNIP_STORE=$(pvesm status --content snippets 2>/dev/null | awk 'NR>1 && $3=="active" {print $1; exit}')
if [ -z "$SNIP_STORE" ]; then
  say "Activation du type de contenu « snippets » sur le stockage local"
  CUR=$(pvesh get /storage/local --output-format json | python3 -c 'import json,sys; print(json.load(sys.stdin).get("content",""))')
  pvesm set local --content "${CUR:+$CUR,}snippets"
  SNIP_STORE=local
fi
SNIP_NAME="hue-sync-${VMID}-user.yaml"
SNIP_PATH=$(pvesm path "${SNIP_STORE}:snippets/${SNIP_NAME}")
mkdir -p "$(dirname "$SNIP_PATH")"

# --- Adaptateur Bluetooth USB ------------------------------------------------
detect_bt() {
  # Interfaces USB de classe "Wireless Controller / RF / Bluetooth" (e0/01/01)
  for intf in /sys/bus/usb/devices/*:*; do
    [ -f "$intf/bInterfaceClass" ] || continue
    if [ "$(cat "$intf/bInterfaceClass")" = "e0" ] && [ "$(cat "$intf/bInterfaceSubClass")" = "01" ] \
       && [ "$(cat "$intf/bInterfaceProtocol")" = "01" ]; then
      dev=$(dirname "$intf")/$(basename "$intf" | cut -d: -f1)
      [ -f "$dev/idVendor" ] || continue
      echo "$(cat "$dev/idVendor"):$(cat "$dev/idProduct")|$(cat "$dev/manufacturer" 2>/dev/null || true) $(cat "$dev/product" 2>/dev/null || echo 'Adaptateur Bluetooth')"
    fi
  done | sort -u
}
if [ -z "$BT_USB" ]; then
  mapfile -t BTS < <(detect_bt)
  if [ "${#BTS[@]}" -eq 0 ]; then
    warn "Aucun adaptateur Bluetooth USB trouvé sur l'hôte : la VM sera créée sans (AirPlay fonctionnera)."
    warn "Tu pourras en ajouter un plus tard : VM > Matériel > Ajouter > Périphérique USB."
    BT_USB=none
  elif [ "${#BTS[@]}" -eq 1 ]; then
    BT_USB=${BTS[0]%%|*}
    say "Adaptateur Bluetooth trouvé : ${BTS[0]#*|} (${BT_USB})"
  else
    say "Plusieurs adaptateurs Bluetooth trouvés :"
    for i in "${!BTS[@]}"; do echo "   $((i+1))) ${BTS[$i]#*|} (${BTS[$i]%%|*})"; done
    read -r -p "Lequel donner à la VM ? [1] " CH
    CH=${CH:-1}
    BT_USB=${BTS[$((CH-1))]%%|*}
  fi
fi
if [ "$BT_USB" != "none" ]; then
  for other in $(qm list | awk 'NR>1 {print $1}'); do
    if qm config "$other" 2>/dev/null | grep -q "host=${BT_USB}"; then
      warn "Cet adaptateur est déjà attribué à la VM $other : il ne fonctionnera que sur une des deux à la fois."
    fi
  done
fi

# --- Image Debian 12 ---------------------------------------------------------
mkdir -p "$IMG_DIR"
cd "$IMG_DIR"
if [ ! -f "$IMG_NAME" ] || [ -n "$(find "$IMG_NAME" -mtime +30 2>/dev/null)" ]; then
  say "Téléchargement de l'image Debian 12 (environ 400 Mo)"
  wget -q --show-progress -O "${IMG_NAME}.part" "${IMG_BASE}/${IMG_NAME}"
  wget -q -O SHA512SUMS "${IMG_BASE}/SHA512SUMS"
  EXPECTED=$(awk -v f="$IMG_NAME" '$2==f {print $1}' SHA512SUMS)
  ACTUAL=$(sha512sum "${IMG_NAME}.part" | awk '{print $1}')
  [ -n "$EXPECTED" ] && [ "$EXPECTED" = "$ACTUAL" ] || { rm -f "${IMG_NAME}.part"; die "Somme de contrôle de l'image invalide."; }
  mv "${IMG_NAME}.part" "$IMG_NAME"
  say "Image vérifiée."
else
  say "Image Debian déjà présente : $IMG_DIR/$IMG_NAME"
fi

# --- Compte utilisateur de la VM ---------------------------------------------
PASS=$(tr -dc 'A-HJ-NP-Za-km-z2-9' </dev/urandom | head -c 14 || true)
HASH=$(openssl passwd -6 "$PASS")
KEYS=""
if [ -s /root/.ssh/authorized_keys ]; then
  while IFS= read -r k; do
    case "$k" in ssh-*|ecdsa-*|sk-*) KEYS+="      - \"${k//\"/}\""$'\n' ;; esac
  done < /root/.ssh/authorized_keys
fi

# --- Fichier cloud-init (user-data) ------------------------------------------
say "Préparation de la configuration cloud-init"
{
cat <<YAML
#cloud-config
hostname: ${NAME}
fqdn: ${NAME}
timezone: Europe/Paris
users:
  - name: hue
    gecos: Hue Sync
    groups: [sudo]
    shell: /bin/bash
    sudo: "ALL=(ALL) NOPASSWD:ALL"
    lock_passwd: false
    passwd: "${HASH}"
YAML
if [ -n "$KEYS" ]; then
  echo "    ssh_authorized_keys:"
  printf '%s' "$KEYS"
  echo "ssh_pwauth: false"
else
  echo "ssh_pwauth: true"
fi
cat <<YAML
package_update: true
package_upgrade: true
packages:
  - qemu-guest-agent
write_files:
  - path: /root/install-hue-airplay.sh
    permissions: "0755"
    encoding: gz+b64
    content: |
      $(installer_b64)
runcmd:
  - [systemctl, enable, --now, qemu-guest-agent]
  - [bash, -c, "bash /root/install-hue-airplay.sh > /var/log/hue-install.log 2>&1 && touch /var/lib/hue-install.done || touch /var/lib/hue-install.failed"]
YAML
} > "$SNIP_PATH"
chmod 600 "$SNIP_PATH"

# --- Création de la VM -------------------------------------------------------
say "Création de la VM $VMID ($NAME) sur le stockage $STORAGE"
NET="virtio,bridge=${BRIDGE}${VLAN:+,tag=${VLAN}}"
qm create "$VMID" --name "$NAME" --ostype l26 --machine q35 --cpu host --bios ovmf \
  --cores "$CORES" --memory "$MEMORY" --balloon 0 \
  --net0 "$NET" --scsihw virtio-scsi-single \
  --agent enabled=1 --serial0 socket --vga serial0 --tablet 0 --onboot 1 \
  --description "Hue Sync : récepteur AirPlay 2 + synchro musique Philips Hue + Bluetooth.%0AInterface web sur le port 8080."
qm set "$VMID" --scsi0 "${STORAGE}:0,import-from=${IMG_DIR}/${IMG_NAME},discard=on,ssd=1" >/dev/null
qm disk resize "$VMID" scsi0 "$DISK" >/dev/null
# Démarrage UEFI : les mises à jour de GRUB de Debian y sont fiables (pas d'invite grub> au redémarrage)
qm set "$VMID" --efidisk0 "${STORAGE}:1,efitype=4m,pre-enrolled-keys=0" >/dev/null
qm set "$VMID" --ide2 "${STORAGE}:cloudinit" --boot order=scsi0 >/dev/null
qm set "$VMID" --ipconfig0 ip=dhcp --cicustom "user=${SNIP_STORE}:snippets/${SNIP_NAME}" >/dev/null
if [ "$BT_USB" != "none" ]; then
  qm set "$VMID" --usb0 "host=${BT_USB},usb3=1" >/dev/null
  say "Adaptateur Bluetooth ${BT_USB} attribué à la VM."
fi

say "Démarrage de la VM"
qm start "$VMID"

# --- Suivi de l'installation -------------------------------------------------
guest_json() { qm guest exec "$VMID" -- "$@" 2>/dev/null || true; }
guest_out()  { guest_json "$@" | python3 -c 'import json,sys
try: print(json.load(sys.stdin).get("out-data","").strip())
except Exception: pass'; }
guest_ok()   { guest_json "$@" | python3 -c 'import json,sys
try: sys.exit(0 if json.load(sys.stdin).get("exitcode")==0 else 1)
except Exception: sys.exit(1)'; }

say "Attente de l'agent invité (premier démarrage + mises à jour, quelques minutes)"
for i in $(seq 1 120); do
  qm guest cmd "$VMID" ping >/dev/null 2>&1 && break
  sleep 5
done
qm guest cmd "$VMID" ping >/dev/null 2>&1 || warn "L'agent ne répond pas encore. L'installation continue dans la VM ; suis-la avec la console série (qm terminal $VMID)."

say "Installation en cours dans la VM (compilation d'AirPlay 2 : 10 à 20 minutes)"
LAST=""
STATUS=timeout
for i in $(seq 1 240); do   # jusqu'à 40 minutes
  if guest_ok test -f /var/lib/hue-install.done; then STATUS=ok; break; fi
  if guest_ok test -f /var/lib/hue-install.failed; then STATUS=failed; break; fi
  L=$(guest_out tail -n 1 /var/log/hue-install.log | grep '==>' || true)
  if [ -n "$L" ] && [ "$L" != "$LAST" ]; then echo "    $L"; LAST=$L; fi
  sleep 10
done

IP=$(qm guest cmd "$VMID" network-get-interfaces 2>/dev/null | python3 -c 'import json,sys
try:
    for i in json.load(sys.stdin):
        if i.get("name")=="lo": continue
        for a in i.get("ip-addresses",[]):
            if a.get("ip-address-type")=="ipv4": print(a["ip-address"]); raise SystemExit
except SystemExit: pass
except Exception: pass' || true)

echo
case "$STATUS" in
  ok)
    echo "============================================================"
    echo " Hue Sync est prêt !"
    echo " Interface web : http://${IP:-<IP-de-la-VM>}:8080"
    echo " Sur l'iPhone  : AirPlay > « Hue Sync »"
    echo
    echo " Accès à la VM : ssh hue@${IP:-<IP>}   (VM $VMID)"
    echo " Mot de passe  : $PASS"
    [ -n "$KEYS" ] && echo " (connexion SSH par clé uniquement ; le mot de passe sert à la console Proxmox)"
    echo "============================================================"
    ;;
  failed)
    warn "L'installation a échoué dans la VM. Dernières lignes du journal :"
    guest_out tail -n 25 /var/log/hue-install.log
    echo "Journal complet : ssh hue@${IP:-<IP>} puis : sudo less /var/log/hue-install.log"
    echo "Mot de passe de l'utilisateur hue : $PASS"
    exit 1
    ;;
  *)
    warn "L'installation n'est pas terminée après 40 minutes (connexion lente ?)."
    echo "Elle continue dans la VM. Vérifie plus tard : http://${IP:-<IP-de-la-VM>}:8080"
    echo "Utilisateur : hue   Mot de passe : $PASS"
    ;;
esac
